import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long q = Long.parseLong(next());
        long[] queries = new long[(int) q];
        for (int i = 0; i < queries.length; i++) queries[i] = Long.parseLong(next());

        int limit = 0;
        for (long x : queries) limit = Math.max(limit, (int) x);
        int[] steps = new int[limit + 1];
        for (int v = 2; v <= limit; v++) {
            int best = steps[v - 1];
            if (v % 2 == 0) best = Math.min(best, steps[v / 2]);
            if (v % 3 == 0) best = Math.min(best, steps[v / 3]);
            steps[v] = best + 1;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) out.append(i > 0 ? " " : "").append(steps[(int) queries[i]]);
        System.out.println(out);
    }
}
